/* 2021年11月30日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r03-20211130-9","dateIso":"2021-11-30","title":"2021年11月30日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5050#one","fetchedAt":"2026-08-14","characters":45798,"voices":[{"i":1,"speaker":"あくつ委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、報告事項、所管事務調査およびその他を予定しております。\nなお、本日の委員会につきましても、新型コロナウイルス感染症拡大防止のため、委員会室のレイアウトを変更するとともに、理事者の出席も必要最小限とさせていただきますので、あらかじめご了承ください。\n最後に、本日も特に会議時間が長時間にならないよう、簡潔かつ効率的なご質疑にご協力をよろしくお願いいたします。\n────────────────────────────────────────────\n１ 報告事項\n(1) 三菱鉛筆による鉛筆リサイクル事業への協力について"},{"i":2,"speaker":"あくつ委員長","text":"それでは、予定表１の報告事項を聴取いたします。\n初めに、(1)三菱鉛筆による鉛筆リサイクル事業への協力についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":3,"speaker":"有馬庶務課長","text":"それでは私から、三菱鉛筆による鉛筆リサイクル事業への協力について、ご報告いたします。\nまず、事業の概要ですが、区内に本社のある三菱鉛筆株式会社が、リサイクルすることを目的とした鉛筆を新たに開発したところです。リサイクルに当たっては、品川郵便局が鉛筆の回収をするということでして、近隣の学校へその事業への協力要請があり、４に記載のとおり１１校で、この事業に協力することといたしました。対象は小学生という形になっております。\n開始に当たりましては、１人に５本、このリサイクル鉛筆が提供されているところでございます。回収されたリサイクル鉛筆は、棒状肥料として、学校に還元される予定でございます。\nまた、従来の鉛筆も、併せて回収をいたします。\n２の事業の目的ですが、児童に身近な文具である、学ぶときに手にする鉛筆をリサイクルすることを通して、児童が資源循環を体験、実感してもらえればと思っているところでございます。\nこの事業は１１月１５日に６校、２５日に１校、残り４校については１２月から開始するということで、今準備しているところでございます。お手元に、三菱鉛筆が作りましたパンフレットも添付してございます。詳細はそちらをご覧いただければと思います。"},{"i":4,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":5,"speaker":"安藤委員","text":"非常にすばらしい取組なのではないかと思います。特にこのリサイクル、もともとごみにならないというとあれですけれど、物を作る上で、その先を見通した製品を作ってそれを流通させるということは、非常に大事なことだと思っていまして、今回最初からリサイクルできるような鉛筆を開発したということなので、そういう意味では、リサイクルという出たものをどうするかというだけにとどまらない、循環型、持続可能な社会に向けて、非常によい取組だし、それを子どもたちに体験してもらうというのは、とてもいいことではないかと思います。\n質問は２つです。区は、具体的には何を協力することになるのか、もう少し具体的に教えてもらいたいのと、協力する学校の選定というのはどのように行われたのか、２点伺いたいと思います。"},{"i":6,"speaker":"有馬庶務課長","text":"まず、今回につきましては、このようなリサイクル鉛筆を開発したということで、三菱鉛筆から申入れがありました。それで、ぜひ身近に学用品として使う、一番消費する小学生に使ってもらい、資源循環ということも併せて学んでいただきたい、というお話がありました。そういった趣旨を受けて、区としても、最終的には自分が使った鉛筆が、最後に芯が残りなくなった部分が回収されて、肥料になってまた戻ってきますよということで、今までアルミ缶とか新聞とか、そういったことは一般にリサイクルされていましたけれども、より身近なものも資源循環になるという可能性がありますということを体験してもらえれば、ということで協力をしていこうとしたものです。\n使い終わった鉛筆を回収ボックスに入れて、それを資源に回わす協力をしていこうというものです。\n選定に当たっては、三菱鉛筆の本社の隣がちょうど品川郵便局で、日常的に協力関係があるということで、回収も品川郵便局が行っていただけるということです。広く一斉にはなかなかできないので、品川郵便局の回収する管内の学校で、協力いただけないかというところでお声をかけたところ、基本的には大井、品川地区が中心でしたけれども、多くの学校が協力をして取り組みますということで、ご協力があったということです。"},{"i":7,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":8,"speaker":"吉田委員","text":"私も本当にいい取組だと思いますし、確かに使えなくなるところまで芯を入れるは必要なかったなと、今、改めて気づいた次第です。\n伺いたいのは、このパンフレットですけれど、循環の絵が書いてあって、こういうことが、ただ鉛筆を回収するだけでなく、どこか授業とかで生かされたらいいなと思うのですけれど、そういうことを考えておられるのかということ。\nそれから、サカタのタネが協力しているということですけれど、この木粉が棒状肥料になるところは、ただ、こうなるんだ、なるほどみたいなことなのか、少しはここを品川区としても、この理屈というか、そういうところは把握しておられるのか。環境の問題というのは、やはりきちんと納得して取り組んでいかないと、どこかで変な方向に行ってしまうことがある事業でもあるのですよ、リサイクルは。だから、そこに品川区のポリシーと、この木粉が棒状肥料に変わっていくこの辺りのことがきちんと、双方の納得と合意のもとに進められたのか、その辺の経緯をもう一度伺いたいと思います。"},{"i":9,"speaker":"有馬庶務課長","text":"まず、これを授業にどうやって生かすかということですけれども、この話を学校に持っていったとき、取り組みたいという学校は、それぞれの思いがあって手を挙げていますので、いろいろな活用の仕方があると思っています。例えば、山中小学校では６年生がこのことを学んで、４年生に伝えて子ども同士でやるとか、八潮学園では生徒会が中心になって回しますということで、生徒会中心に動いているとか、いろいろなやり方が今出てきておりますので、子どもたちにもリサイクルというのは浸透しているのかなと思っています。\nもう一つ、この木粉から棒状肥料になるところは具体的には、まだ詳しくは、こちらと向こうで何か詰めていることはありません。場所がどこかとかもまだ、これはなかなかオープンにしないで開発をずっとしていたものですから、詳細についてはこれからなのですけれど、例えば工場見学みたいなことができるのかなど、そういったことはまだ全然詰めていないので、今後の話になってくるかなと思っております。"},{"i":10,"speaker":"吉田委員","text":"まだ、これは本当に始まりということで、分かりました。\nリサイクルということでいえば、子どもたちの活動とかそういうことが、本当に子どもたちの自主性や環境意識を育てる意味でも非常に重要だと思うのですけれども、日本の森がどういう現状になっていて、これは別に突っつくつもりではないのですが、木材がフォレストサポーター鉛筆になっていくということですけれど、ここに間伐材の利用とかそういう視点があって、これは言葉の定義かもしれないですけれど、木材にならないものが貯木場に山のようにたまっていたりしますよね。そういうものを活用するという視点があって、その前に日本の森を、もっと言えば東京都も森はとても多く占めていますので、その森の現状がどうなのか、どういう状況にあって、これを取り組むことによってどういうふうに生かされていくのか、というところまで、全部の子どもたちでなくても、関心を持った子どもたちがそこまでの理解ができるようになると、この取組自体がとてもよいものになるかなと思います。そこに品川区がきちんと関与するというのは、とてもよい政策だと思っていますので、ぜひ今後のことも含めて、これ自体は本当にいいと思います、第一歩としてやっていただければと思います。"},{"i":11,"speaker":"松本委員","text":"すばらしい企画だと思います。パンフレットを拝見しているのですけれど、裏面に「木づかい.ｃｏｍ」という三菱鉛筆のサイトが出てくるのですが、サカタのタネとか出てくるのは分かるのですけれど、木づかい.ｃｏｍ、これはどういった経緯で載せているのか、なぜ載っているのか、どういうご認識なのでしょうか。"},{"i":12,"speaker":"有馬庶務課長","text":"このパンフレット自体、三菱鉛筆が作成しておりますので、その細かい経緯まではこちらは把握していない状況です。"},{"i":13,"speaker":"松本委員","text":"分かりました。これは子どもたちに配布されるものなのでしょうか。"},{"i":14,"speaker":"有馬庶務課長","text":"子どもたちにこの中の資源循環を理解してもらうために、１人１枚配るというふうに聞いております。"},{"i":15,"speaker":"松本委員","text":"分かりました。子どもに配るものなので、一応どういう中身で、サカタのタネが開発に関わったというのはプレスリリースで、インターネット上にも出ているのでいいのですけれども、品川区の教育委員会含めて４社以外のものが出ているので、そこがどういうものなのか調べると、何か違和感がある団体ではないのですけれども、載っている以上は調べていただければと思います。\nいずれにしてもすばらしい企画だと思うのですけれども、こういった環境関係の企画というのは、もちろん子どもたちについてもとても大事なのですけれども、やはり保護者の方たちだと思うのです、環境について学ぶというのは、大人になってしまうとなかなか機会がないので、こういったパンフレットを、例えば家に持ち帰って、家族で話し合ってみようとか、そういうふうに学校から子どもにアプローチをして、子どもたちが保護者と一緒に考えるというようなことができたら、本当はいいかと思うのですけれども、その辺り、子どもだけではなく、保護者も含めた学びの機会ということについてはどのようにお考えでしょうか。"},{"i":16,"speaker":"有馬庶務課長","text":"今回の取組につきましては、従来使っている鉛筆の回収も当面やっていこうということでございますので、家庭の協力が必要だということは、学校のほうも認識しております。当然保護者のほうにも、これからこういう鉛筆のリサイクルを始めます、新しい鉛筆が支給されます、これは使い終わったら回収しますし、短くなった鉛筆は回収しますということでご案内をするということですので、そういったところで理解を深めていただければと考えております。"},{"i":17,"speaker":"松本委員","text":"これはあくまで要望で、各学校の裁量だとは思うのですけれども、せっかくタブレットもありますので、パンフレットを配るというのももちろん大事ですし、今回のプレスリリースそのものでなくてもいいと思うのですけれども、中身について保護者の方たちもインターネット上からご覧になれるような仕組みというか、通知というかお知らせの仕方をしていただければと思います。\n以上、要望です。"},{"i":18,"speaker":"つる委員","text":"本当に素敵な取組だと、伺っていました。\nこの４社の協力ということなので、分かる範囲で結構なのですが、品川郵便局、大きくいうと日本郵便株式会社になるのですけれども、ここは協力関係でいくと、回収したものを三菱鉛筆の工場か何かに届けるという、役割というのはそれだけなのですか。何かほかにあるのか教えてください。"},{"i":19,"speaker":"有馬庶務課長","text":"私が三菱鉛筆から話を聞いている中では、回収に携わる、協力してくれるというふうにだけ聞いております。肥料をどこかへ持ち込むとか、そこまでの話は特段聞いていないです。"},{"i":20,"speaker":"つる委員","text":"これは三菱鉛筆が主となってつくり上げた仕組みという理解なのですけれど、いずれにしてもすばらしい取組で、いろいろなプレスを確認すると、約１年間が、この実証実験の期間と設定されていると思うのですが、「品川モデル」というふうに、メディアなのか、三菱鉛筆が言っているのか分からないですけれど、品川モデルを構築して展開していくと。先ほどご説明の中にもあったかもしれないですけれど、そういう場合はいろいろな関係から、当然全国展開を期待したいというところと、今回の場合は三菱鉛筆から１人当たり５本を提供となっているわけですけれど、全国展開になってくるといろいろな、この１年間というのは実証実験ですが、商業ベースにしっかりと、営利の企業としてはやっていかなければいけないというところで、環境配慮とこのすばらしい循環をつくっていかなければいけないというところでは、後においてはそういう形になるのかなと思いながらも。いずれにしても品川区全区で、各学校で展開すると、環境教育とかいろいろな部分で資すると思うので、本当にすばらしい取組だと思いました。\n一つ、鉛筆自体は品川郵便局で購入できますというふうになっているのですが、どういう単位で売っているのか、１本なのか１ダースなのか分からないですけれど、幾らぐらいするものなのでしょうか。"},{"i":21,"speaker":"有馬庶務課長","text":"今のところ、１本１２０円で１ダース１,４４０円と聞いておりまして、郵便局に設置している様子を見ると、おそらくダース単位で売っているのではないかと思われます。１本単位で売っているかどうかまでは確認できませんでしたけれど、箱でカウンターに並べて販売しているというような状況は、確認しております。"},{"i":22,"speaker":"つる委員","text":"分かりました。個人的にも購入していきたいというところで。ただ、単価自体は、通常の鉛筆より少し高いのか。今、小学校は就学に際して名前入りの鉛筆にしたりしますね。その単価がどうだったか。いずれにしても、この仕組み自体というか、こういう鉛筆は当然、消費者の選択になるわけですけれど、増えていくことが望ましいと思います。\nそれで、鉛筆の芯が残っているものについてはバイオマス発電ということで、これはＣＯ２がほぼ出ないやり方ですね。こちらについては、今この仕組みの中では１１校となっていますけれども、鉛筆自体の回収というのは、学校とかでやっていたりするのですか。結構短い鉛筆、いろいろなアダプターをつけて使うとかいうことはあったりするのですけれど、その回収もやれたらと思うのですけれど。これは今、各学校ではどうなっているのか。ちょっと余談なのですけれど、もし分かれば教えてください。"},{"i":23,"speaker":"有馬庶務課長","text":"一般的に、今、鉛筆自体は廃棄物扱いになっていて、いわゆるリサイクル品目ではないので、有価物というかリサイクル品目として集めるのは難しいらしいのです。実態としては、恐らく各学校では、鉛筆を集めていないのでないかと。今回のこの実証実験につきましても、リサイクルを目的としますということで、三菱鉛筆も清掃事務所に、廃棄物でなく、資源化物ということでの回収を認めていただきたいと交渉していると。そんな経過もあるということでございます。"},{"i":24,"speaker":"つる委員","text":"そういうことを聞くとますます、今後の展開に期待したいと。そこまで事業者の方が、いろいろ汗をかいて、こういう仕組みをつくり、子どもたちが学習で使う一番身近な道具が、そういう環境に配慮しながら自分たちもそれに資することができるという、すばらしい取組なので、この辺り、あくまでも軸は三菱鉛筆だと思うのですけれども、いろいろないい声をお届けして、ぜひとも全国展開を、当然、営利の部分はそれはそれとして、仕組み自体はいろいろな形で展開できるように、行く行くは品川区でも山北町とか、自治体間交流しているところの森とか、これは国産材のヒノキですけれども、そういったことにも展開できるのかなと思います。ぜひその辺も、教育委員会からもぜひお声を届けていただければと思います。"},{"i":25,"speaker":"松澤委員","text":"私も大変すばらしい取組だと思ってございます。それで、すみません、聞き逃したかもしれないのですけれど、これは取りあえず品川郵便局の範囲内で１１校がスタートしますけれど、今後、全部の小学校でやる予定でしたか。"},{"i":26,"speaker":"有馬庶務課長","text":"そこはまだ三菱鉛筆も、ここでまずやってみてということで、回収を品川郵便局の協力を得ているところもありまして、今後、うまくいけば区内に限らずいろいろ考えているようですけれども、まだ具体的に、そこについて案があるわけではございません。"},{"i":27,"speaker":"松澤委員","text":"ありがとうございます。私、本当に、こういうものはすばらしい取組だと思っています。\n先ほど松本委員からお話がありましたけれど、親も一緒に学ぶというのは、私はすごくいいことだと思っています。ＰＴＡでは家庭教育学級、委託事業でありますけれど、何かああいうので一回やってみるとか、学校公開で親が見に来るときに一緒に学ぶというのは、私はとても大切なことだと思いますので、ぜひそういった部分も含めて、親と学べる環境学習、そういうものを考えていただけたらと思います。"},{"i":28,"speaker":"あくつ委員長","text":"ほかにございますか。\nでは、私からも１点。すばらしい取組だと思うのですけれども、ここに書いてある内容、また三菱鉛筆のホームページを拝見すると、ＳＤＧｓそのものなのですね。いわゆる持続可能なものをつくっていこう、仕組みをつくっていこうという。ＳＤＧｓの１５番目、「陸の豊かさも守ろう」、そういうことも志向されているのかなと。三菱鉛筆はほかの自治体と、ＳＤＧｓに関して協定を組んだりもされているので。今回は実証実験ということで、それは表に出てきていないのですが、先ほどつる委員からもありましたけれど、プレスリリースを見ると、「品川地区にて実証実験を行い、「品川モデル」を構築した後、徐々に展開地区を拡大する予定です」と。今までの質疑でもありましたけれど、うまくいけば全国展開なのか、どんどん増やしていきたいという考えがあると。そのときに、もしかすると三菱鉛筆はＳＤＧｓを冠するのなと思うのですが。\n品川区で実証実験をするに当たって、もし意見交換をする場があれば、「品川モデル」と銘打つのであれば、ＳＤＧｓというところもしっかり、世界において、品川区が、子どもたちがこういうことをやっているのだ、世界の中の位置づけとして、そういうものもぜひ入れたほうがいいのではないかということは、ぜひお願いしたいと思います。\n環境学習交流施設もこれからできます。これは所管が違うのですけれども、例えばそういうところに、今後展開していく中で回収ボックスを設けるとか、そこで販売をするとか、そういった展開もできるのかなと。それは企業が考えることなのでしょうけれど、もし、これから品川モデルと冠がつくようであれば、ぜひそういったところも意見として述べていただければありがたいと思います。"},{"i":29,"speaker":"有馬庶務課長","text":"まさに委員長がおっしゃったとおり、この取組はＳＤＧｓですねという話は、最初に話合いを持った時、三菱鉛筆と交わしております。そういったところで、今、学校もＳＤＧｓに取り組んでいるので、ぜひ協力していきたいという話は、最初にさせていただいていますので、その辺のところはまたより一層、三菱鉛筆と確認しながら進めていきたいと考えております。"},{"i":30,"speaker":"あくつ委員長","text":"ありがとうございました。\nそれでは、他にご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 令和３年度家庭教育講演会の開催について"},{"i":31,"speaker":"あくつ委員長","text":"次に、(2)令和３年度家庭教育講演会の開催についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":32,"speaker":"有馬庶務課長","text":"それでは私から、令和３年度第２回家庭教育講演会についてご説明いたします。資料をご覧ください。\n今回のタイトルは「家庭で考えるコロナ禍での子どもの心」と題しまして、講師に臨床心理士の湯野貴子さんを招いて、オンラインで開催する予定でございます。\n湯野貴子さんは、子どものケアに当たるなど日常的にも活動されておりまして、最近では、立正大学の心理学部の公開講座、これは９月１８日に実施されたものですけれども、そこでも「コロナ禍のメンタルヘルスを考える」ということで、特に子どもですとか、その親に焦点を当てたお話をされていらっしゃいまして、その話をきっかけに今回、講師依頼をしたということでございます。\n今回は１２月１６日に収録を行いまして、配信を年末から年始にかけて行いたいと思っております。コロナ禍での学校生活が長引いていることもあり、丸印の一番下ですけれども、講演冒頭に教育長から、保護者の皆さんへメッセージをお伝えできればと思っています。\nそういったことも含めまして、ＵＲＬが決まり次第、文教委員の皆さんにはお伝えしたいと考えている次第でございます。"},{"i":33,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。\nよろしいですか。\nご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(3) 令和４年度 入学希望申請の状況について"},{"i":34,"speaker":"あくつ委員長","text":"次に、(3)令和４年度入学希望申請の状況についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":35,"speaker":"勝亦学務課長","text":"それでは私から、令和４年度の入学希望申請の状況につきまして、ご説明させていただきます。資料をご覧ください。\n来年４月、令和４年度の入学希望申請につきまして、例年通り１０月１日から３１日までの期間で受付をいたしました。希望申請の状況と、それに伴う抽せん校についてまとまりましたので、ご報告させていただきます。\nまず、１ページ目でございます。新１年生の状況でございます。大きなくくりで、左が令和４年度、真ん中が令和３年度、右側が令和２年度という形で、過去と次年度を掲載してございます。表の見方でございますけれども、学校名の隣の（ａ）が学校の通学区域内の住民基本台帳に載っている方の数字になってございます。その右側が希望申請数となりまして、増（ｂ）が、ほかの学校からこの学校に入学を希望されている方、その隣の減（ｃ）は、ほかの学校への入学を希望されている方、転出される方になります。その隣、令和４年度入学予定者数は、こちらの住基人口（ａ）に対する増（ｂ）、減（ｃ）を差引きしたものでございます。その隣の受入枠につきましては、来年度学校で受入れを予定している数でございまして、こちらは７月の本委員会でもご報告し、入学案内のパンフレットにも掲載している数字でございます。\n小学校・義務教育学校前期課程のそれぞれの数値につきましてはご覧のとおり、表にしてございますけれども、合計欄のほうをご覧ください。住民基本台帳上の合計３,４６８人の方が、今年の１０月１日現在の数となります。このうち、通学区域以外の学校を希望された方が、合計で６９５名いらっしゃいます。\n申請の割合でございますけれども、一番下の欄外をご覧ください、２０.０％。入学予定者の５人に１人の方が希望申請を出された計算となります。令和３年度につきましては２１.６％でしたので、今年は１.６ポイントほど減ってございます。\n抽せん校につきましては、網かけになってございます。２５校が抽せん校となります。先ほど申し上げました一番右の欄の受入枠の数字を超えた入学希望者をそのすぐ左の数字が超えている学校が、基本的に抽せん校となります。ただ、５番の城南第二小学校、９番の第四日野小学校は、受入枠は超えていないのですけれども、それぞれの希望申請の減（ｃ）で相当の方の数が、これらの学校以外を希望申請している状況にございます。外に出ていきたいと希望されている方々が、それぞれ希望先の学校に入れればよろしいのですけれども、希望先の学校が希望者の多い学校になりますと、抽せんで外れて、残念ながら戻ってくる方もたくさんいらっしゃるということになりますので、その点を見込みまして、今の時点では抽せん校とさせていただいております。\n続きまして、中学校のほうへ参ります。裏面２ページ目をご覧ください。こちらも基本的には新１年生と同様でございますけれども、一部異なっているところがございます。学校名の隣の住民基本台帳上の人数の隣、学区外児童数（ｂ）という欄がございます。こちらは、学校の通学区域にお住まいで、今、学区外の義務教育学校に６年生として通っている方の数になります。義務教育学校は義務教育９年間一貫の学校でございますので、７年へ進級するときには、通学区域を問わずそのまま進級できることにしてございますので、そのまま在籍している義務教育学校に進級されるであろうという予定で、整理しております。\n一番下の合計欄をご覧いただきますと、１０月１日の住民基本台帳上の入学予定者数は２,７６６人。希望申請をされた方が５７８人、申請率にいたしますと２０.９％、こちらも５人に１人という割合になってございます。昨年は２３.７％でしたので、２.８ポイント減といった状況でございます。\nちなみに中学校の場合ですと、例年３割程度が私立学校のほうに就学される状況でございます。参考までに令和３年度、真ん中の枠をご覧いただきますと、１０月１日の住基人口は２,６９２人ですけれども、実際４月１日に入学された方は、一番右端になりますけれども１,６７０人ということで、１,０００人ぐらい減っているという状況でございます。\n抽せん校につきましては、こちらの表も網かけをしている学校でございます。考え方は同じで、受入枠を超える入学予定者数があるところを抽せん校としてございます。数字上は１１校ございますけれども、このうち、２番の大崎中学校、３番の浜川中学校、７番の荏原第五中学校、１１番の伊藤学園、こちらの４校につきましては、私立学校への進学がここ数年非常に高い傾向にございます。ここを判断いたしまして、辞退される方がほかの学校より多いだろうと見込んでございまして、抽せんを行わずに入学予定者数の受入れができるだろうと判断してございます。このため、１１校から４校除外いたしまして、７校が抽せん校となります。\n今後の予定でございますけれども、抽せん校に関しましては、本日から１２月３日にかけまして、学校ごとに抽せんを行います。抽せんの結果を受けまして、１２月下旬にそれぞれのご家庭へ、就学指定の通知を発送することになってございます。この抽せん結果等につきましては、今後の文教委員会にてご報告させていただければと考えているところでございます。"},{"i":36,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":37,"speaker":"安藤委員","text":"学校選択を希望される方が年々減っているのですけれど、逆に子どもの数は増えていると。なぜ減っているのかというのは、どういうふうに分析されているのでしょうか。まず伺いたいと思います。"},{"i":38,"speaker":"勝亦学務課長","text":"選択の希望につきましては、ここ数年、減が続いてございます。人口につきましては、ご覧いただいたとおり増加してございまして、実数でも減少してございます。この因果関係につきましてははっきり分かりませんけれども、やはり人口が増えたことによりまして、抽せん校が増えている状況で、なかなか希望するところに入れないという考え方もあるのかもしれません。また、ここ数年、希望者が減っていることに関しましては、コミュニティ・スクールの導入ですとか、そういった地域とのつながりを重視しているのではないかと考えているところでございます。"},{"i":39,"speaker":"安藤委員","text":"今のご説明を聞いても、学校選択制を続けていく必要性は疑問だなと。必要性どころか、私たちの会派は、いろいろな弊害がありますから、やめろと言っているのですけれど。\n続けて伺いたいのですけれど、学校選択制をやる理由として、今までも何回か聞きましたけれど、選択をさせることで、そういう言い方はしませんけれど、子どもの獲得競争に学校を追い立てるわけです。その結果、活性化すると。活性化という言葉をお使いになっていますよね。学校選択制をやることで、学校が活性化するということを一つ挙げておられます。もう一つは権利保障という話をされていました。\nでも、もうもはや選択する人が２０％なのですよね。５人に１人しか選択しないという状況で、それ以外の５分の４の方々は選択しないわけではないですか。その２０％のために、わざわざこういう大がかりな、物すごい手間をかけて、地域と学校のつながりを分断して、子どもの獲得競争と、それを判断するための一斉学力テストの点数競争に追い立てるという弊害をつくってまで、こういう制度、もはや続ける必要はないのではないかと、私は思うのですけれど。\nこの２０％のために、そういった大きな弊害をつくり続けるという選択制を、区教委はやり続けるのでしょうか。伺いたいと思います。"},{"i":40,"speaker":"勝亦学務課長","text":"学校選択制を続ける意義があるのかという点でございます。まず、繰り返しになりますけれども、学校選択制につきましては、活性化という言葉を使われておりましたけれども、特色のある学校活動、選ばれる学校づくり、選んでもらえる学校づくり、そして教員の意識改革といったところ、また、保護者の権利保障といいますか、選択の幅を持ちたいという要望、希望があるという状況から、実施しているものでございます。実際、２０％につきましては希望申請が出ているということで、２０％のニーズはあるというふうに考えてございます。\nまた、地域とのつながりの分断というところにつきましては、品川区の小学校につきましては、もともとブロック制、地域に根づいた形で、今般の新しい制度でも隣接校への選択という形で、選択の幅を設定してございます。そういった形で、先ほど申しましたコミュニティ・スクールの実施ですとか、区の町会活動の支援の中で、地域とのつながりはより強固になっていると考えてございます。"},{"i":41,"speaker":"工藤指導課長","text":"ご質問の中で、学力定着度調査が、選択制において学校を選ぶ際の指標に使われているというご指摘がございましたけれども、学力定着度調査につきましては、各学校がその児童・生徒の実態を把握し、それぞれ児童・生徒がまだ足らない部分は定着し、学力を伸ばすこと、また、それに対して教員は授業改善に資するために行っているものでございますので、学校間の比較をするために行っているものではございません。"},{"i":42,"speaker":"安藤委員","text":"今、様々ご反論がありましたけれど、結果的にホームページで公表していて、やはり一斉学力テストの点数を見て選ぶという人は、実際いるわけです。結果的に競争、選択の材料にしてもらうということが区教委の狙いでしょうから、言葉ではそういうことは認めないでしょうけれど、結果的にはそうなっているということなのです。\nそれと、特色ある学校づくりをするために、選択制をしないとそれができないというのは、何というか、動機づけが間違っているし、私は先生に対する信頼がないのかというか、そういう教師不信を前提にしたモチベーションのつけ方というのは、根本的に間違っていると思いますので、選択制は改めていただきたい。地域とのつながりもいろいろやっていますと言いますけれど、そもそも選択制で地域とのつながりを根本から分断しておいて、そういった弥縫策ではありませんけれども、様々な手を打っているといっても、何の説得力も私はないと思います。\n続けて質問に移ります。城南小学校と御殿山小学校、芳水小学校の３校については、希望すれば必ず入学させなければいけないのが、この住民基本台帳の子どもの数だと思うのですけれども、これが既に受入枠の数を大きく超えている現状であります。さらに、希望申請の増減を踏まえた入学予定者数、こちらも受入枠の数を大きく超えているということは、受入れをしなくてはいけない、かなりの数の人が、恐らくここに行くのだろうと推測されるのですけれど、すなわち学級を増やさなくては対応できない、トップ３校なのではないかと思うのです。さらに来年からは国が正式に始めた３５人学級が、２年生まで拡大するわけですよね。\nだから、必要な学級数を整備するための見通しを、この３校で持っておられるのか伺いたいと思います。また、具体的に来年度、普通教室を幾つ増やす計画があるのか、伺いたいと思います。\n併せて、これまで３５人を超えた学級編成をしていた、第二延山小学校については、今年はそもそも基本台帳の数が少ないということになっておりますけれど、こちらの見通しについても伺いたいと思います。"},{"i":43,"speaker":"勝亦学務課長","text":"今、城南小学校、御殿山小学校、芳水小学校、併せて第二延山小学校の見通しということで、お問合せいただきました。基本的な考え方といたしましては、委員おっしゃったように、学区内にお住まいの方につきましては、必ず全員受け入れるという形になってございます。そういった意味で、学区内にお住まいの方が３５人学級の設定を仮に超えた場合は、学級数の増についても検討するような形になってございます。第二延山小学校につきましても、同様の考え方でございます。\nまた、来年度につきましても、こういった３５人学級の拡大もございますので、３０教室程度の増を見込んでございます。そういった形で受入れができるように、各校、対応の準備をしてございます。"},{"i":44,"speaker":"安藤委員","text":"もう一度確認なのですけれど、来年度、区全体として新たに学級数を増やす普通教室は、３０教室ぐらいを予定しているということでよろしいのか、もう一度確認させてください。\nそれと、超えた場合は、国が３５人でやると言っているわけですから、その教室の増設と併せて、そういった場合でも対応できるということでよろしいのか。もう一度伺います。"},{"i":45,"speaker":"勝亦学務課長","text":"来年度、３０学級程度の増を見込んでいるものでございます。\n繰り返しになりますけれども、学区内にお住まいの方については、３５人学級の増、もしくは経過措置がございますので、その経過措置の利用等々含めて、学校の状況を確認しながら、学校とも相談しながら、決定してまいりたいと考えております。"},{"i":46,"speaker":"安藤委員","text":"しつこいのですけれど、３０学級ぐらい増えそうだという見通しは持っている、それは分かりました。もし増えた場合にはきちんと対応できるように教室も整備すると、今準備を進めているということでよろしいのか。そこだけ再度確認します。"},{"i":47,"speaker":"勝亦学務課長","text":"申し訳ございません。３０学級程度の増を見込んで、その対応をしているということでございます。失礼いたしました。"},{"i":48,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":49,"speaker":"松本委員","text":"先ほど学校選択制の意義の話が出たかと思うのですけれども、２０％といっても、私は選択できるということはとても重要なことだと、２０％というところをもって数が少ないというのは、いささか言い過ぎた面があるのではないかと思うところです。\n学力との関係という話も先ほどから出ているのですけれども、学校を選ぶ、保護者と子どもたちに選択肢があるとき、選ぶ理由は別に学力だけではないと、当然ながら思うのですけれども。この点について、例えばアンケート等を行って分析というのは、定期的にやられたりしているのか、お伺いしたいと思います。"},{"i":50,"speaker":"勝亦学務課長","text":"学校選択の希望申請を受けるに当たりまして、併せて希望した理由をアンケートでとってございます。今年度の分につきましては、まだ集計が終わってございませんので、後日報告させていただきたいと考えておりますけれども、昨年度につきましては、小学校ですと、１位が学校の教育活動、２位が学校の近さ、学校の新しさ、もしくは友人関係、そういったものが重視されているという結果が出てございます。中学校につきましては、友人関係や学校の近さといったものが出てございます。\nそういった意味では、友人関係ですとか近さ、そういった地域の部分が重視されているのかなというふうに捉えているところでございます。"},{"i":51,"speaker":"松本委員","text":"ありがとうございます。これは保護者の選択というところがあると思うのですけれども、児童の選択というところもあると思うのです。家族と話し合って、どういうふうに自分の進む小・中学校を選ぶか、ということはあると思いますので、私としては、もろもろ課題はあるとは思うのですけれども、それはしっかりと対応していきながら、こうした子どもたちに選択肢を与えていくという、競争という部分とは別に、極めて意義があることだと思いますので、よりバージョンアップしていくように、これはもう毎回考えられていることだと思うのですけれども、引き続き、教育委員会の中で切磋琢磨といいますか、いろいろと検討していただければと思います。\n以上、要望です。"},{"i":52,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":53,"speaker":"松澤委員","text":"説明ありがとうございます。今の松本委員からの質問で、アンケートがとられているという中で、学校の活動であるとか、新しい、家に近いとありましたけれど、その回答は、自由に保護者が書けるものなのか、それとも選択項目があって選ぶのか、どちらなのか教えてください。"},{"i":54,"speaker":"勝亦学務課長","text":"アンケートにつきましては、選択肢をこちらのほうで提示いたしまして、複数回答式という形で集計してございます。"},{"i":55,"speaker":"松澤委員","text":"ありがとうございます。先ほどからの選択制、特色ある学校をというお話は理解しております。そうなりますと、抽せん校がある一方で、明らかに年々、入学者数が減っている学校も実際にあるわけですよね。そうすると、何といいますか、特色がよく見えていないのか、うまく伝わっていかないのか、何かそんなふうに感じてしまうのですけれども。こうやって明らかにどんどん減少していく学校について、何か教育委員会のほうで、その学校との話合いというか、そういうことは持たれるのですか。"},{"i":56,"speaker":"勝亦学務課長","text":"児童・生徒数の状況につきまして、年度で学級を編成する中で、各学校と協議をしながら編成を進めているところでございます。"},{"i":57,"speaker":"松澤委員","text":"一般質問でも言わせていただいたのですけれども、学校選択制というのはあると思うのですよね。でも、その中で、小学校と中学校の連携校はあるのですけれど、学区が違う。それを理解しない保護者と子どもからすると、やはりどうしても、連携校でやる選択のやり方というのもあるのかなと、私は個人的に思うのですけれども。今は小学校５年生からもう中学校に行って、部活をやるのですよね。そうすると子どもは、その学校に絶対行くものだと思ってしまう。でも、実際の抽せんは違う学校なのだというと、やはりそこはもう心理的な、計り知れないつらさがあるかと思います。\nそのグループ連携校という考え方の部分で、ちょっとお答えをいただけたらと思います。"},{"i":58,"speaker":"勝亦学務課長","text":"学校のグループ、連携校といった部分と学区の問題は、別の制度ではございますけれども、そういった部分につきまして、まずご案内の段階で理解が十分進むようなお伝えの仕方、こちらはパンフレットですとか、そういった中でしっかり伝えていければと考えてございます。\nまた、現状でございますけれども、連携校への進学につきましては、学校選択の中で優先順位をつけまして、一般の方よりも高い優先順位で入学ができるように措置してございます。\nその他、また課題があるようでしたら、できるだけ公平な制度になるように研究してまいりたいと考えてございます。"},{"i":59,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":60,"speaker":"吉田委員","text":"今、学校選択制の話になっているのですけれども、生活者ネットワークとしては、学校選択制についての評価は、周りの中でもいろいろ分かれるところなのです。何よりも大きな問題だったと思うのは、そういう制度を変えたりするとき、どの程度当事者の方たちの参加のもとで議論が進められたのか。一番問題だったのは、急に変わってしまい、決定した後知らされるというのが、一番お声が入ってくるのですね。いつ決まったのか、というのが。もちろん教育委員会としては手順を踏まれたというふうに思われるのでしょうけれど、なかなかそれが現場の方たちには伝わっていないというところが問題だと思っています。\nそれで、それを前提にした情報の出し方なのですけれど、私のごく身近には入学する子どもとかいないので、どのような情報が今、これから入学予定者に渡されているのか分からなくて、ある区民の方に、品川区は学校選択制をとっていますので、と言ったら、「いや、選択制になっていませんよ、今」と。配られたパンフレットには、おたくのお子さんはここに行くことになりますという書き方だと、いうふうに言われたのです。でも、「いや、今は制度としては選択制なのです。ただ、選べないような現状もあるのは確かで」というようなやり取りを、つい最近していて。その方は、もう選択できないのだと思っているのですよ。\n今、その方にどういうお便りとかが、多分、来年学校に入られる方で、何かその情報の提供の仕方がどうなのでしょうねというのが、一点あります。その学校は今のところ選べないのかなと。行く予定の学校も聞いているのですけれど。今の情報の出し方というのがどうなのかという、基本的なところを伺いたいと思います。"},{"i":61,"speaker":"勝亦学務課長","text":"学校の情報の出し方ということで、まず就学学齢のお子様には全員に対しまして、学校教育法の施行令の中で、就学の指定というものがございます。そちらにつきましては、住所地で指定させていただく形になりますので、一度、全ての方に、指定の学校はここでございます、という通知になります。その中で併せまして、品川区では学校選択制ができますということで、そのご案内とパンフレット等をお送りしているところでございます。"},{"i":62,"speaker":"吉田委員","text":"分かりました。多分その最初のところを読んで、もうそうなのだと思われてしまったのですね。私は選択制ですという説明をしましたので、私の説明も間違っていなかったし、理解していただけたかなというふうに思います。\nそれで、先ほど選んだ理由のアンケートのお話もありましたけれども、項目が幾つかあってということで、ごめんなさい、聞き漏らしたかもしれないのですけれど、自由記述はあるのでしたか、ということを伺いたいと思います。"},{"i":63,"speaker":"勝亦学務課長","text":"学校選択を利用された方へのアンケートにつきまして、複数の選択肢を提示してございますけれども、その他ということでご記入いただける欄も用意してございます。"},{"i":64,"speaker":"吉田委員","text":"その他の理由が書けるのですか。「その他」だけですか。"},{"i":65,"speaker":"勝亦学務課長","text":"失礼いたしました。その他ということで、自由記述ができる欄を設けてございます。"},{"i":66,"speaker":"吉田委員","text":"分かりました。これは、今この状況がどうかというご報告ですので、議論が学校選択制の問題になっているのですけれども、現状は選択制をとっているわけですから、それを前提として、学校を選ばれる方もいらっしゃるのは事実です。今後どうなるか分かりませんけれども、まず、一番今必要なのは、その希望のところに入れなかった方へのフォローといいますか、そういうことと、それから、もし今後またこういう議論があるのであれば、ぜひきちんと、広く議論をした後の決定が必要かと思います。\n学校選択制の最初のときは、残念ながらそれが足りなかったというのは、私たちのところに入ってくる情報としては多いので、ぜひその辺のことは、今のこのご報告とはずれるかもしれませんけれど、意見として申し上げておきたいと思います。"},{"i":67,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":68,"speaker":"つる委員","text":"まさに我が家も、封筒を開けて、書類を見て、今、吉田委員が指摘したような、たくさん書類が入っていて、１枚目はそういう書類があって、２枚目、３枚目、４枚目、冊子も入っていてという。これはいろいろ、見方というか、要するに、基本は住所地の学校はこちらですというのは、どんと分かっていて、その上で品川区は学校選択制というのを設けていますという、そういう段取りだから、書類の順番とかいうのは、別にいいのかなとは思います。ただ、分かりやすくというのは、そうだなと、今、拝聴していましたけれども。\n先ほどの中学校のほうで、これは学校選択ではないところでも出てくるのですが、いい意味での評価というところで、かつてこの委員会でも言ったことがあるのですけれども。小学校から中学校で、いわゆる私学への進学率が３０％後半ぐらいで続いているというのは、一貫教育とかいうところの視点にもなってくるのですけれども、やはり小学校での基礎学力等を含めた公教育の中で、しっかりとやっていただいているからこその、私学への数字の大きさという部分で、それは評価ですか、どうですかという質疑をかつてしたことがあるのですけれど。そこが今、そのぐらいの数字で出てきているという中で、いわゆる選択については一定程度、希望の中で入っていっている傾向があるのかなと思って。\n一方で、小学校受験の方も、当然いると思うのです。今、中学校受験は品川区では３割強ぐらい、進学がそうですよね。ということは、受験率というのはもっと多いと思うのです。となってくると、小学校での進学率というのは、どのぐらいになるのでしょうか。分かれば教えてください。"},{"i":69,"speaker":"勝亦学務課長","text":"私立小学校への進学ということでのお問合せでございます。こちらで把握している限りでは、大体３％から５％ぐらいの人口が、それに当たるのかと見ているところでございます。"},{"i":70,"speaker":"つる委員","text":"そうすると、大体今月の頭とか先月ぐらいで、試験があったり発表があったりという流れが、小学校受験についてはあるのかなと思っていまして。そうすると、令和２年度、３年度を見ていくと、住基上の数、それから実際の入学者数を単純に引き算すると、令和２年度が４.６％、３年度が７.１％、その中で私学の受験者がいるということですね。という理解を勝手にしたのですが。あとは区外への引っ越し等ですね。\n先ほど、選択制のいろいろな話もあったと思うのですが、近年で見ると２５％、２１％、２０％という感じで希望される方が少なくなってきているというのは、逆に言うと、この制度にしてから各学校が努力をして、自分の住基上の学校も優れていて、自分たちにとって魅力のある学校になってきたという、逆の意味での表れという捉え方もできるのではないかと、私は先ほどの質疑を聞いていて思ったのです。だから、年度によって、とても人気が集中する学校はあると思うのですけれども、だんだんそれが平準化してきているというのは、そういう部分の評価があるのかなと思うのですが、この辺りというのはどう捉えていますでしょうか。"},{"i":71,"speaker":"勝亦学務課長","text":"今、委員おっしゃいましたように、平準化の部分でございますけれども、こちらのほうとして、大規模校、小規模校、合わせまして、それぞれ地域に納得いただけるような情報発信ですとか、信頼していただけるような教育活動、そういった部分が、地域との連携の中で地域の方にご理解いただいて、地域のほうに、帰ってきているという言い方はおかしいかもしれないですが、地域の学校がより選ばれているという状況なのではないかというふうに考えてございます。"},{"i":72,"speaker":"つる委員","text":"ぜひ、いろいろな意味でも品川区立の小学校を選んでいただいて、入っていただいて、先ほど中学校の受験率という部分も確認させていただいたのですが。この私学への進学率というのは、推移というのは、近年どのぐらいなのか分かりますか。分かれば教えてください。"},{"i":73,"speaker":"勝亦学務課長","text":"私学への進学率の推移でございますけれども、中学校で申し上げますと、平均しますと大体３割程度が続いているような状況でございます。"},{"i":74,"speaker":"つる委員","text":"関連する問いだったので、それで結構です。いずれにしても、要は今回の申請状況ということも含めて、いろいろなところで学校を選んでいただいて、６年間はこの品川区立の小学校で学び、いろいろなそれ以外のプラスアルファの学習、学力をつけていくという努力というのは、各ご家庭、各児童がやっていって、中学校での受験という、それは以前も言ったのですけれど、プラスの評価の部分なのだろうなと思うのです。一貫教育という積み上げの９年間というのはあるのですけれども、やはりそれだけの学力を公立の学校だけれども提供している、そういう環境を整えているのだというところで、また、その基礎となる小学校が、それぞれの学校の努力によって力をつけることによって、いろいろな選択もされるでしょうし、また自分の住んでいるところが優れていいという評価もあるのでしょうし、そういう意味では切磋琢磨の部分に資していることなのだろうなと。\nただ、その上で、それ以外の細かい部分、法で位置づけられている指定校変更とかの部分、それは制度の部分になってくると思うのですが、どちらがどちらを補っているのかという部分もあろうかと思うのですけれども、その辺りについても、結局そのような制度もあるのですねという、先ほどの吉田委員の質疑ではないですけれど、書類上ではなかなか分からない部分もあって、選択はしたけれども、まだそういう余地もあるのだ、というお声も伺っているところなのです。ですから、それは例えば先ほどのクラスを幾つにするかとか、住基上あれば、それは受け入れていかなければいけないから、クラスを増やす学校もいろいろある中で、指定校変更の枠の中で行けるのであれば、そちらを選択したいと。そういうご意見もあるわけですよね。そういったところももう少し、非常に大変な作業なのかもしれないですけれども、保護者、また子どもたちでも分かりやすいような書類、そういったものも作っていただきたいと思います。\n最後、この申請状況の資料で、令和３年度、令和２年度とそれぞれあるのですけれども、一番右側には最終の入学者数が入っているわけですが、この数字の中には、今申し上げた指定校変更で入られたお子さんも入っているわけですね。だから、いろいろな意味で、あえて指定校変更枠の数字というのは入れていないのかと思うのですけれども、もし、支障がない部分の検討がされて、可能であれば、そういったところの数字も分かるといいのかと。様々な事情があって変更せざるを得ないというところで、そういった配慮の中ではないかという部分もあると思うのですが、もし可能な範囲であれば、ぜひ検討いただければと思います。"},{"i":75,"speaker":"あくつ委員長","text":"ほかによろしいでしょうか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(4) 令和３年度（４年度採用）品川区立学校教育職員採用候補者選考状況について"},{"i":76,"speaker":"あくつ委員長","text":"次に、(4)令和３年度（４年度採用）品川区立学校教育職員採用候補者選考状況についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":77,"speaker":"工藤指導課長","text":"それでは私から、令和３年度、４年度採用になります、品川区立学校教育職員採用候補者選考状況につきまして、資料につきましては、Ａ４の１枚でございます、こちらをもとにしながら、説明させていただきます。\nまず初めに１、第一次選考ということで、令和３年７月１７日土曜日に行ったところでございます。受験申込者総数は１５名でございました。ただ、当日３名が辞退されまして、受験者は１２名でございました。選考の結果は、１０名を合格としたところでございます。\n続きまして、２の第二次選考でございますが、令和３年８月２８日土曜日に実施いたしました。対象者は第一次合格の１０名ということで行いました。全員が受験され、面接の結果は、４名を合格者としたところでございます。\n３の採用候補者面接でございますが、いわゆる最終面接でございます。令和３年９月１８日土曜日に実施いたしました。対象者であります４名全員が受験いたしまして、受験者４名のうち３名を採用内定者として、決定したところでございます。"},{"i":78,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":79,"speaker":"安藤委員","text":"前回は令和２年度に向けた職員採用候補者選考があったと思うのですが、その時に比べてかなり数が減っているのですけれど、前回の申込者数は６１人ということで、第二次選考の受験者も、前回は２２名いたということだったのですけれど。今回、少ないのはなぜなのか、理由を伺いたいのが１点です。\nそれと、今回で区独自採用教員の３０名の採用が完了する予定なのか、そうだと思うのですけれど、３０名の採用を完了するとなると、それは全額単費というご答弁もかつてあったのですけれど、年額幾らぐらいの事業費になるのか。それは単費なのでしょうけれど、財調の算定対象にはならないということなのか。\nあと、３０名を区が独自で財源を出して採用するわけですけれど、当然、都が開示している教員定数とは別に、自由にできる３０名が品川区に配置されるという考え方でよろしいのか。\n幾つか伺いますが、お願いします。"},{"i":80,"speaker":"工藤指導課長","text":"まず、少ない理由というところでございますが、確かに令和元年度に実施した選考は、ご指摘のとおり６１名という受験申込者総数でございましたけれども、これにつきましては、東京都また他県と同様に、現在、教員採用試験申込者そのものが減少しているという現状でございますので、そういったことが要因の一つであるというふうに考えてございます。また、その他の要因といたしましては、昨年度は感染症拡大の影響がありまして実施を見送ったということで、２年ぶりの開催だったというところで、いわゆる周知の部分で課題があったというふうに認識しております。\nまた、周知の面では、大学が現在オンライン授業に切り替わっているということで、学生が校舎に来ないということがございます。これまで受験者の方に聞いたところでは、校舎内に掲示したポスターなどで、品川区で実施していることに気づいたといいますか、それが分かったということが多かったものですから、北は北海道、南は沖縄まで各大学には送付しているのですけれども、学生そのものが校舎に来なかったという部分も勘案すると、私どもの情報発信の仕方については、今後、採用選考を行うに当たっては考慮しなければいけない課題であると認識しているところでございます。\nまた、今回３名に内定を出したところでございますが、３名を合わせると、現状２７名おりますので３０名が完了するという目途で進めているところでございます。\n事業費総数でございますが、およそでいきますと１人当たりおよそ４００万円から５００万円、人件費として計上して、いわゆる職員として任用するものでございます。総数は３０名いますが、職層がそれぞれ分かれておりますので、今、手元に資料はないのですけれども、そういったことで、この３名分については予算計上させていただいているところでございます。\nまた、予算としましては、これは品川区の職員ということでございますので、品川区で、現状はいわゆる職員給与の中での配分としてというふうに、私どもは考えておりますけれども、そういったことで、費用については考えているところでございます。\n定数につきましては、都費の教員とは全く別で、品川区独自で都の定数にプラスとなるものでございますので、都費の定数には影響ないものでございます。"},{"i":81,"speaker":"安藤委員","text":"最後のところは当然そういうことだと思いました。ありがとうございます。\nであるならば、やはりその３０名の活用というのはとても重要になってくると思うのです。\nあと、先ほどの質問で、財調の算定にもならないということですか。区が職員としてやっている、完全単費ということで。完全単費という用語があるのか分からないですけれど、そういうことだと思います。間違っていたら、後で訂正してください。\n独自教員について、これまで区教委が述べておられましたのは、市民科について中心的な役割を担っていることが多いと。そのほか、英語教育とか一貫教育の中で特徴としているものを中心に、業務を担っているというようなご答弁もしていましたし、また、年６回の独自の区固有教員への研修を組んでいるとも説明されてきましたけれど、いまいち分からないのですよね。一方では、都の教員と変わりませんよという言い方もされているので、都の採用の教員とどのような違う業務を行っているのか、もう少し具体的に説明していただきたいと思います。"},{"i":82,"speaker":"工藤指導課長","text":"都の教員と違うところでいいますと、例えばご指摘いただいたように、市民科の学習内容でありますとか、その指導の方法も含めて、市民科の理解というのは、やはり固有教員については、もちろん全ての者が理解しているところでございますが、特に異動で新しく品川区にいらっしゃった先生がいる場合には、校内での研修のリーダーになるというところで、年間通じてリーダーになっている者も多くございますので、そういった意味で推進の核となっているものでございます。\nまた、品川区独自で行っている、例えば一貫教育の中の英語教育についても、英語教育の体系であるとか、そういったものも含めて全て理解しておりますので、やはり、それぞれの先生方の理解を助けるというところでは、品川区の教育を適宜説明するという役割も担っているところでございます。\nまた、今後においても、特にタブレットの活用が今、始まっているところでございますが、１人１台タブレットで本区ではｉＰａｄを活用しておりますけれども、都費の教員の場合は、異動によって他地区に行ったり、また他地区から来た場合には使っている機種も違うことがございますが、固有教員につきましてはｉＰａｄに入っているアプリも含めて、その熟練をしていくことによって、さらにその活用も図れるというところでございます。やはり品川区が行っている一貫教育も含めた、教育施策そのものの継続、また発展には寄与していくものと考えているところでございます。"},{"i":83,"speaker":"安藤委員","text":"研修もやっているということですけれど、大変なのかなと、お話を聞くと思いました。せっかく３０人の方を採用するということなので、その方々の活用というところは、私はそういう、今とられているような、というよりはむしろ、杉並区の例を何回か紹介させていただきましたけれど、そこでは７０人弱の独自採用教員をとっているわけです。品川区の場合は市民科の教科にあてているかもしれませんけれど、その分を杉並区では、さらなる少人数学級の全学年の実施の前倒し等にあてているわけですから、私は全体の教育環境の充実ですとか、少人数学級の推進とか上乗せのために、ぜひ活用していただきたいと、改めて要望させていただきたいですし、そういった活用でさらなる独自採用を、３０名にとどまらず、さらに進めていただきたいと思っております。\nこれは要望です。"},{"i":84,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nでは、私から１点。一次選考のところで受験者の内訳が、一般が５名、経験７名となっていて、最終的に内定者は、一般の方が３名ということで、経験者の方はゼロということになっています。普通に考えると、一般の方というと、新卒なのか分かりませんが、比較的年齢が若いのかなと。ほかの自治体の教員等、品川区も含むのでしょうけれど、経験のない方が多いのかなと思います。経験者というのは、年齢制限もあるのでしょうけれど、それなりの年齢の方なのかなという中で。これは例年の傾向なのか、何かそこに、どういう理由があるのか、たまたまなのか。そこら辺について教えていただければと思います。"},{"i":85,"speaker":"工藤指導課長","text":"ご指摘いただいた、いわゆる一般と経験の区分での、今回内定者は一般だけだったということで、この一般に該当しますのは、現在大学４年生と、卒業した方でいうと、代替教員であるとか、臨時的任用教員の経験が１年未満の者ということでございます。本区では、臨時的任用教員を１年以上やっている者も経験者枠ということで、一次試験の試験問題を一部免除にするというふうに優遇を図っているところでございますが、そういった意味では、一次のところで一定程度申込みはいただいているところでございます。\nこれまで私ども採用した中では、経験者で合格されている方というのは、いわゆる私立を含めた正規教員をしている者という方が多くございました。今回の受験者の中の経験者で、いわゆる私立あるいは他県等での正規教員という方はいらっしゃいませんでした。現在、経験はあるのですけれども、非常勤であるとか、臨時的任用教員の経験を現在もしている方も含めて、ということでございました。\n選考基準といたしましては、一次試験での免除規定があるだけで、あとは全て同じ選考基準で行っていますので、あくまでもそういった選考をした結果、一般の方のみ３名が合格だったというところでございます。"},{"i":86,"speaker":"あくつ委員長","text":"分かりました。やはり区の職員になる方ということですので、受験をしていく中で、ほかの経験をされている方が、なかなか品川区の教育委員会の考え方、品川区の考え方ということに対して、お話をしていく中で難しいのかなという方もいらっしゃるのかなという印象を受けたものですから、質問させていただきました。これだけでは読み取れない部分もあったので、質問させていただきました。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(5) 図書館システムの機能向上作業時における停止について"},{"i":87,"speaker":"あくつ委員長","text":"次に、(5)図書館システムの機能向上作業時における停止についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":88,"speaker":"吉田品川図書館長","text":"それでは私から、図書館システムの機能向上作業時における停止について、ご説明いたします。資料をご覧ください。\n１番、概要についてです。図書館システムの機能向上のために、システムのバージョンアップ作業を実施いたします。作業時においては、全図書館システムを停止する必要があります。図書館利用者への影響を最小限にするため、図書館への来館者がない全区立図書館の休館日である、年末年始の休館期間に実施いたします。ただし、インターネットを利用した予約システムについては、当該作業中、利用者サービスを停止するところです。\n２番、停止するシステムについてです。図書館システムは大きく、公共図書館システム、学校図書館システム、インターネットからの図書予約システム、この３つのシステムで構成されています。その全てが停止いたします。\n３番、システム停止日です。令和４年１月３日月曜日の午前９時から午後５時までとなります。この日は年末年始の全館休館日となっております。\n４番、機能向上の内容ですが、新たな機能として主なものを申し上げます。希望者になりますが、貸出資料の返却期限日が近づいた際に、利用者向けのお知らせメールの送信機能の追加や、使いやすさへの対応としましては、予約画面等における選択ボタンの拡大、日付入力の簡素化、これは内部的な改善となりますが、運用側の画面等の表示項目の追加、改善、そのほかのものとなります。\n５番、周知につきましては、広報しながわ、区ホームページ、図書館ホームページ、ツイッター、フェイスブック、各区立図書館窓口等におけるご案内を実施いたします。"},{"i":89,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":90,"speaker":"安藤委員","text":"利用者の方から言われたのですけれど、今回、システムの機能向上ということですが、図書館内の検索端末で検索すると、必ずしも品川区の図書館に置いていないものも含めてヒットするということなのです。逆にそれだと不便なのです、みたいな話がありまして。少なくとも検索するとき、品川区の図書館内のみの検索に絞れるように改善してもらいたいという要望があったのですが、そうだったかなと思ったのですけれど、事実どうなのかということも含めて、今回の機能改善に入っているのか、入っていないのか。入っていなければ、ぜひそういったところも改善していただけないかと思うのですけれど、いかがでしょうか。"},{"i":91,"speaker":"吉田品川図書館長","text":"そのお問合せにつきましては、図書館内のＯＰＡＣという検索システムがございます、そのシステムについてのご質問かと思います。図書館内で使うＯＰＡＣ、蔵書検索システムについては、近隣および国会図書館の資料も含めて、表示する仕組みとなっております。そのため、一般の図書館内で検索する際には、そこも全部表示されるような、もともとそういう仕組みとしてやってまいりました。\n通常、今はパソコンとかでご自宅、もしくは館内の端末から操作される際には、その機能は特に付加してはおりません。その違いのところでございます。"},{"i":92,"speaker":"安藤委員","text":"なるほど、やはりそうなのですね。それでは逆に、ヒットし過ぎて逆に不便だというような話があったので、図書館内の検索端末ではそういう全体のものをヒットできるし、絞って検索できるような機能も、付加してもらえないかというご要望だったので、その辺りについては、ぜひ改善してもらいたいのですけれど、いかがでしょうか。"},{"i":93,"speaker":"吉田品川図書館長","text":"今回の機能追加につきましては、特に他の自治体、国会図書館との連携の部分についての修正は入っておりませんので、現状どおりの仕組みのまま行く予定でございます。\n逆に、その機能があることを便利とされている方もございますので、その辺のところはまた、利用者の声等お伺いしながら、考えたいと思っております。"},{"i":94,"speaker":"安藤委員","text":"それは便利だという人もいるので、今回は難しいと思うのですけれど、次回以降の改善で、そういう検索もできるし、そこを除外した検索も、区内の図書館だけとかでも検索できますというふうな、選択できるようにしてもらえないかという話なので、そこら辺は今後ぜひご検討の材料に入れていただければと思います。"},{"i":95,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":96,"speaker":"松澤委員","text":"すみません、勉強不足で教えていただきたいのですが、学校図書館システムというのは、区立図書館とネットワークでつなぐという、そのシステムでいいのか、教えてください。"},{"i":97,"speaker":"吉田品川図書館長","text":"委員、ご指摘のとおりでございます。基本的には、品川図書館のシステムがありまして、それに対して学校図書館システムが連携しながら、つながっておりまして、そのシステムを各学校が利用しているという形になっております。"},{"i":98,"speaker":"松澤委員","text":"ありがとうございます。少し調べたのですが、これは平成１７年、品川区が２３区初ということで、すばらしいなと思ったのですけれど、平成１９年に約６割の学校に学校図書館システムが整備されたと書いてあるのですけれども、その後、今は全学校で、この学校図書館システムというのは使われているのか、そこだけ確認させてください。"},{"i":99,"speaker":"吉田品川図書館長","text":"今、委員のご指摘のとおり、区立小学校、中学校、義務教育学校、含めまして、全ての区立の学校で、学校図書館システムは稼働しているところでございます。"},{"i":100,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":101,"speaker":"つる委員","text":"システムの機能向上内容のところにある、利用者向けお知らせメールの送信ですが、返却が迫ったとか、これは初めての取組ですね。非常にいいことかなと思うのですが、議会のいろいろな委員会でも、未返却の本についての質疑が幾つかあった中で、私も自分自身、その辺どのぐらいなのでしょうかというやり取りを、たしか記憶しているのですが。品川区で今、実際に未返却の本というのは、年間でいいのですけれども、令和２年度は冊数と金額にすると、どのぐらいあったのかというのは分かりますでしょうか。"},{"i":102,"speaker":"吉田品川図書館長","text":"未返却の数字については、今、手元に用意してないところでございます。申し訳ございません。"},{"i":103,"speaker":"つる委員","text":"今、手持ちでないけれども、戻ればあるという理解をしました。全国の図書館が、図書館法で定められているので、例えば欧米のように延滞料を課すとか、そのようなことはできないという法の縛りの中で、なかなかモラルの部分で悩ましい。品川区が今、それをやっているかどうか分からないのですが、はがきを送ったり、直接訪問して返してくださいとか、それも当然人件費とか様々な経費がかかると思うのです。だから今回こういう、さらにモラルに訴える部分なのですが、相手が明確で、その人に直接そうやって、そろそろ迫っていますよというのは、非常にいいアラートかなと思います。\nなので、システムを改修して、未返却の数がどれだけ減っていくのかという部分などは、しっかりと見ていっていただきたいと思います。そもそも返却されないということはないのがいいのですけれど、その辺はしっかりと、数値として把握していただきたいと思います。\nそれと併せて、除籍にする本がありますよね。その年によって違うでしょうけれども、毎年どのぐらいあるのかということと、今確認させていただく中では、図書館の本のリサイクル市とかやっているのは、図書館で使っていた本が、一定期間たてばリサイクルとして皆さんにご活用くださいと、当然、転売は駄目ですよと、なっているかと思うのですけれど、その辺の扱いについて教えてください。"},{"i":104,"speaker":"吉田品川図書館長","text":"除籍の数につきましては、ほぼ年間購入した数と同じだけのものを、現在は除籍にしているところでございます。"},{"i":105,"speaker":"つる委員","text":"細かい数字はいいです。"},{"i":106,"speaker":"吉田品川図書館長","text":"また別途、数字につきましては、また改めて。リサイクル市につきましては、当然、館内で持っていて、例えばベストセラーだと最初のうちに多く買いましたけれど、大分余ってきたとか、利用率が下がってきたとか、そういうものにつきましては一定程度、図書館としての在庫は持ちますけれども、リサイクルという形で、月１回とか、図書館でお配りするということを今やっているところでございます。"},{"i":107,"speaker":"あくつ委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(6) 武蔵小山図書取次施設の臨時休館について"},{"i":108,"speaker":"あくつ委員長","text":"次に、(6)武蔵小山図書取次施設の臨時休館についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":109,"speaker":"吉田品川図書館長","text":"それでは私から、武蔵小山図書取次施設の臨時休館について、ご説明いたします。資料のほうをご覧ください。\n１の概要についてです。きゅりあんの大規模工事に伴いまして、３階にある男女共同参画センターが、令和４年１月２９日に武蔵小山図書取次施設、旧荏原第一地域センターの一部改修後に、仮移転してまいります。移転作業中は、施設前に引っ越し用のトラックの停車があるなど、また引っ越し業者や職員が頻繁に行き交うと共に、現在の施設が２階のため、机、椅子等什器の搬入に当たりましてはエレベーターを占有して、作業等を行います。また、男女共同参画センターの移転に合わせて、図書取次施設の利便性等を考えまして、現在の通路に奥まった、この地図でいいますと、現）図書取次施設と書いてある場所から、２階のフロアに上がりまして、すぐ左奥になります、新）図書取次施設の場所に移動させます。\n移転当日は警備員等の配置も行いますが、より利用者や地域の方々の安全性を確保するため、武蔵小山図書取次施設については、臨時閉館いたします。武蔵小山図書取次施設、旧荏原第一地域センターの住所については、表記のとおりです。図面は２階部分となります。\n２の図書取次施設の臨時休館日は、令和４年１月２９日土曜日といたします。\n３の周知方法につきましては、広報しながわ、区ホームページ、図書館ホームページ、ツイッター、フェイスブック、各区立図書館窓口におけるご案内を実施いたします。"},{"i":110,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":111,"speaker":"安藤委員","text":"移転の理由がいま一つよく理解できないのですけれど、初めから、図の左上の場所で取次施設を開館することができなかったのかなと思うのですけれど、そこについて伺いたいと思います。"},{"i":112,"speaker":"吉田品川図書館長","text":"左側のところにもともと移転できなかったことなのですけれども、まず最初に今年、引っ越しをしてくる際に、一番使いやすい形をしていたところと、あと、最終的にはこの左上の新）図書取次施設のところを使いたかったのですけれども、こちらに改修をかける必要がございました。その関係で、最初からそこに入ることができなかった次第です。まず、内装などをきれいにしてから、最終的にはそちらに入ろうと計画していたので、まずは、この地図で会議室となっているところに、仮に入らせていただいて、その後全体の、男女共同参画センターの引っ越しを含めての内装をやって、全部整備された後、私ども取次施設が、会議室から左上の第二集会室のほうに移るという予定で進めていたところでございます。"},{"i":113,"speaker":"あくつ委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件および報告事項を終了いたします。\n────────────────────────────────────────────\n２ 所管事務調査\nコロナ禍における子どもたちの心のケアについて"},{"i":114,"speaker":"あくつ委員長","text":"次に、予定表２の所管事務調査を議題に供します。\n本日は、７月７日の委員会において決定しました、所管事務調査項目、コロナ禍における子どもたちの心のケアについてを調査項目とします。\nまず、理事者より、資料に基づきご説明をいただき、その後、ご質疑、ご意見等をお願いしたいと思います。\nそれでは、本件につきまして、理事者より説明をお願いいたします。"},{"i":115,"speaker":"矢部教育総合支援センター長","text":"それでは、大きな資料に基づきまして、コロナ禍における子どもたちの心のケアについて、ご説明いたします。\n初めに、昨年度より現在もなお、区立学校版感染症予防ガイドラインに基づきまして、学校は日々の検温や手洗い、密の回避、咳エチケットなどの徹底をしております。また、学校行事につきましても、学年や時間、参観者の制限などをして、感染対策を講じながら工夫をして、実施しているところでございます。\n初めに、１の児童・生徒の実態についてでございます。\nこの調査は、１１月１日の時点で、お子さんたちの現状を臨時に調査したものでございます。\n(1)コロナ不安を理由に登校していない児童・生徒数は、９月１日は３９５人でしたが、１１月１日には３９人に減少しております。このことは、１０月２５日に東京都の緊急事態宣言が解除されたことによる児童・生徒および保護者の安心感を反映したものと捉えております。\n(2)緊急事態宣言解除後の児童・生徒の様子について、全体的な印象を学校に尋ねたところ、７０％の学校から、改善したという答えが上がっております。\nまた、(2)で改善したという理由につきましては、左から２番目の枠になります。教育活動について、(3)のグラフのとおり、行事の実施、外部人材を招いた授業、校外学習の拡大などが多く挙げられました。そのほか、実験や実習の機会が増えたという回答もございました。\n(4)の、「変わらない」「改善していない」と答えた理由としましては、行事は可能になったが、まだ変化はない、不登校が増加した、コロナ対策は変わらないから、などの理由がありました。\n続きまして、(5)不登校児童・生徒につきましては、令和元年度と令和２年度を比較しますと、国や東京都と同様に増加傾向でございます。ただし、児童・生徒の数と不登校児童・生徒数の割合を示す出現率を比べますと、東京都よりは低いところでございます。\n続きまして、(6)の虐待相談件数につきましては、教育総合支援センターだけの対応分ではございますが、令和元年度と比較しますと、８３件から１５８件と、約２倍近く増加してございます。\n続きまして、(7)いじめについては、令和元年度と比較して、令和２年度は減少しております。このことは国の傾向と同様でございます。\n続きまして、右上の黄色の部分です。心のケア、各学校の取組例でございます。\nそちらにございますとおり、校長の講話、「学校だより」「カウンセラーだより」等で、不安の緩和、いじめ・差別防止、相談体制や窓口の紹介。担任や養護教諭による観察・相談、家庭への連絡。「生活アンケート」やｈｙｐｅｒ－ＱＵ、これは全５年生対象に行っていますが、その実施と対応。スクールカウンセラーによる全員面談、５年生、７年生と行っております。\n３点目、一番下になります。登校できない児童・生徒の支援例でございますが、当該児童・生徒の保護者と相談した上での実施になります。例えば、担任が毎日電話で、体調や家庭での過ごし方を聞く。これは希望によりますけれどオンラインによる授業の参加。保健室や別室での登校などが行われております。"},{"i":116,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑、ご意見等がございましたら、ご発言願います。"},{"i":117,"speaker":"安藤委員","text":"資料に基づいて幾つか質問します。まず、１番の（１）のところで、コロナ不安を理由に登校していない児童・生徒ということで調査をされているのですけれど、この定義というのですか、どのように算出している数字か、伺いたいのが１点目です。\n２点目ですけれど、（２）と（３）です。児童・生徒の様子とあるのですけれど、改善したという理由が、これを見ると学校運営上の問題で、子どもの様子が改善したというのは、この（３）を見ると必ずしもそう見えないのですけれど、そこら辺はどうなのかというのが２点目です。\nそれと不登校のところですが、コロナ前とコロナ後で不登校がどれだけ増えているかというのは、やはり大事な点だと思うのです。不登校の定義を教えてもらいたいのと、２０１９年と２０２０年の不登校の児童・生徒、つまり品川区で言うと前期課程、後期課程というのですか、小学生、中学生の数を伺いたいと思います。\nそれと、あちこちですみませんけれど、出現率が都に比べて低いと書かれているのですけれど、この低い要因というのは、区はどのように考えているのかも伺います。"},{"i":118,"speaker":"矢部教育総合支援センター長","text":"大きく５点いただいたかと思います。１つは、算出です。コロナ不安を理由にというのは、このとおりでございまして、これからも多分ご質問が出るかもしれませんけれども、不登校気味なお子さんも含めて、とにかくおうちでコロナが不安ですという申出があった、その数字でございます。\n２点目は、子どもの様子が分からないというところなのですが、学校としては様々アンケートをとったり、毎日担任は会っていますので、その印象は持っているのです。私どもとしては、お子さんの様子を直接調べているということはないので、その学校からの声、学校から見た観察の模様を上げてもらっているというような調査になります。\n３点目、不登校につきましては、年間３０日を超える、病気は除きますけれども、様々な理由で学校に登校したくても来られない児童・生徒の数でございます。\n続きまして、令和元年度と２年度の不登校の児童・生徒数の数でよろしいでしょうか。令和元年度は１年生から６年生までが１２１人、令和２年度が１６１人、７年生から９年生は、令和元年度が１９５人、令和２年度が２３７人になっております。\n続きまして、都に見比べて出現率が低い要因は、私たちとしましては、まず様々な学校の取組と、我々のＨＥＡＲＴＳも含めた関係機関との連携と支援、また市民科での指導も当然関係してございます。また、先ほどの話題にもありましたが、学校を選べるということでは、保護者同士、また子ども同士でどうしてもうまくいかない場合、選んで別の学校に行くことも考えられるという学校選択制も、関わっているのではないかと分析しております。"},{"i":119,"speaker":"安藤委員","text":"最後のところは、不登校というのは非常に、原因が単純にこうだとも言えない、単純に言ってもいけないものだと思っているので、確かにその原因は何か、難しいところなのですが、今のご答弁は、私はちょっと納得が、市民科の指導、選択制と言われても、納得できないところであります。\n不登校の数ですが、先ほどご答弁ありましたように、小学校で前年度から３３％増えていて、中学校で２２％増えていて、やはり明らかにコロナで増えているのではないかと思うのですけれど、そこについてどのように分析されているのか。\nそれと、分かればでいいのですけれど、２０２１年はまだ途中なのですけれど、現時点での直近の数字、今回、物すごい第５波を経験した年度でもありますので、さらにその傾向がどうなっているのか知りたいので、直近の数字でいいので、分かれば同じような数字も教えていただけないかと思います。\nそれと、この不登校の数というのは、やはり数字としてはきちんと把握する必要があると思っていまして、今回、一般質問でも高橋しんじ議員が質問したのですけれど、数はお答えになりませんでしたし、今回の資料に載っていませんし、もっと言えば毎年の事務事業概要にも載っていないのですよね。事務事業概要自体が教育委員会の所管は簡素過ぎて、いつも不満はあるのですけれど、こういうのは、少なくとも品川区の教育の状況を客観的に把握する一つの数字なので、もう少し資料あるいは所管事務調査にも、ルーチン的に載せる必要があるのではないかと思うのですけれど、そこら辺はいかがでしょうか。"},{"i":120,"speaker":"矢部教育総合支援センター長","text":"３点いただいたと思います。１点目、増えている要因でございますが、これはコロナ禍ということを考えますと、昨年度からでございますが、相談員に聞きますと、子どもたちは初め６月は、昨年度４月、５月がお休みだったとき、逆に分散登校になって出やすくなったという現状がある一方で、その後だんだんお休みになってきたというところ、そこは学校のほうで、かなり行事を精選して、楽にはしたのですけれども、時には学年だけ組んで運動会をやるとか、今までとは違ったパターンで、なかなか追いつかないお子さんもいたというふうには聞いています。そういったパターンが変わってきたことの適用が難しいということは、聞いております。\nあと、今回も１１月１日の現状でまだ何人かいますので、このお子さんたちのことを考えて、もともと不登校の傾向がある中で、もしかしたらコロナを理由にお休みのハードルが、学校に行かなくてもいいというハードルが下がったのではないかということが、聞かれております。そのようなことが出ています。\nあと、２点目の直近のお子さんの数ですけれど、実はこれは３０日たったところでカウントしていくので、年度の終わりにならないと分からないというのが、国への報告についてもですので、私たちとしては聞き取りの中で、お子さんの登校渋りが増えている、増えていないというところでしか、数としては出ていません。ただ、今年度も昨年度と同様、少し登校渋りのお子さんがいるというのは聞いてございます。\n３点目、公表していくかどうかということなのですが、これまでも求めに応じて、その年とか、これまでの経年についてはお話ししてきたつもりでございますが、私たちとしましては、今、子どもの数も増加していることもあって、当然、不登校のお子さんも数としては増えていくと思うのです。今回の調査も数字を挙げるということよりは、どうやってそういう子どもたちを救うかというための調査をしていますので、そのような活用でご理解いただければと思います。"},{"i":121,"speaker":"安藤委員","text":"私は、改善する上でも実態をテーブルに載せるというのが第一歩だと思うので、これは所管事務調査なので、ぜひほかの委員の皆さんのご意見も伺いたいのですけれど、私はそういうところというのは、きちんと議会は把握できるように、議会のみならず、区民ですよね、事務事業概要も含めた情報公開というのは必要だと私は思っています。\nそれと、続けて２番と３番のところの質問もしてしまいますけれど、２番は、細かいところで申し訳ないのですが、スクールカウンセラーによる全員面談、５・７年生とありますが、これはどのようなことを、いつからやっているものなのか、目的と成果などを伺いたいと思います。\n３番は対策のことが書いていますけれど、登校できない児童・生徒の支援という点では、いろいろ手段はあると思うのですけれど、人的な体制を厚くするというのは一つ、決定的なのではないかと思いまして。川崎市などでは、児童支援コーディネーターというのを専任配置しているのですね。教員というのは自分の学級を持っているわけですから、自分の学級の中で不登校の方が出ても学級を離れるわけにいかないし、不登校だけれど保健室ぐらいには行こうかなという、一人一人にきめ細かく対応というのはなかなか難しい中で、教員や養護教員のほかに、クラスを持たない、不登校を含めた支援が必要な子どもの支援に専念する教師というのが、別にいるということなのです。私の知り合いの川崎市で教員をしている方も言っていたのですけれど、すごく助かっているという話もありました。もうその人がいないなんて考えられない、みたいなことを言っています。\n品川区での状況はどうでしょうか。そういう配置はあるのでしょうか。ないとしたら、誰がそのような役割を担っているのか、伺いたいと思います。"},{"i":122,"speaker":"矢部教育総合支援センター長","text":"こちらに示してありますスクールカウンセラーは、東京都の配置でございます。すみません、正確な年度が不明で、後でお調べしますが、もう５年ぐらい前から、スクールカウンセラーは５年生と７年生につきまして全員面談することが決まっておりまして、主に１学期の早いうちに面談をしてございます。\nそれと成果につきましては、たくさんお子さんがいますので、一人一人にじっくり時間がなかなかとれないのが現状でございますが、顔とか名前とか覚えて、そこがきっかけになって、その後相談室につながるとか、そういう目的が大きなところでございます。規模の小さな学校につきましては、丁寧にできている可能性もあります。\n続きまして、人的体制の整備でございます。現状は、学校と家庭の連携事業というところに国と東京都が補助金を出して、そちらに本区も手を挙げてございます。そちらのほうでは、別室の中で支援がついておりますので、委員がおっしゃったような、そのお子さんに合わせた学習指導とか、話し相手とか、また家庭訪問も行っている学校がございます。また、同時に不登校の対応で加配校もございますので、そこには教員が１人配置されているということで、それぞれそのような対応でございます。\n先ほど、スクールカウンセラーの成果のこともおっしゃったと思いますけれど、成果は先ほど少し触れましたけれども、顔と名前を覚えて、その後つながって、相談しているということも聞いてございますので、それは一定の成果があると考えております。手を挙げて、相談したいという人だけがこれまで来ていたのですけれども、５年生、７年生については、とにかく１回は接触しますので、そういう機会として大変重要だと捉えております。"},{"i":123,"speaker":"安藤委員","text":"スクールカウンセラーは、確かに一回顔を合わせると、そのときに深刻な相談がなくても、相談のハードルがぐっと下がるという点では、大変だなと思いますけれど、有効というか、いい事業なのではないかと思います。それだけにスクールカウンセラーは、きちんと常駐で学校にいないといけないのではないかという思いを強くしましたので、その辺の人的体制の補強はぜひお願いしたいというのが、まず要望です。\nそれと、川崎市の例も紹介しました。いろいろやっているという話ですけれど、実態として全ての学校で、川崎市では児童支援コーディネーターというのを制度化しているので、どの学校に行っても、不登校を含めた児童支援に専念する、教員免許を持った教師がいるということなのですね。それはかなり大きい、人的な厚い体制だと思うのです。そういうことを品川区ではやられているのか。全部の学校でそういう、いろいろな方々がいるという話もありましたけれど、そういう体制がとられているのか。ぜひそういう体制をとるべきだと私は思うのですけれど、最後にご見解を伺いたいと思います。"},{"i":124,"speaker":"矢部教育総合支援センター長","text":"全ての学校では、基本的には生活指導主任が担当になっております。ただし不登校やいじめについては、管理職にも必ず報告することになっておりますので、１人というよりは生活指導部会、また学校体制の中で取り組んでいると認識しております。"},{"i":125,"speaker":"あくつ委員長","text":"委員長からお願い申し上げます。すみません、これはお願いです。今もご熱心な質疑で大変ありがたいのですが、進行上の問題もありまして、長時間にわたっておりますので、所管事務調査ということで、多分たくさんお聞きしたいことはあると思うのですけれども、なるべく端的に、皆さんが公平に質疑ができるような形で、よろしくお願いいたします。\nでは、ほかにご発言どうぞ。"},{"i":126,"speaker":"吉田委員","text":"先ほどの質疑の中でも出てきたのですけれど、１番の（３）、（２）で「改善した」と答えた理由となる教育活動というのは、この教育活動の結果が改善につながりましたという意味でいいのかというのが１点。だから、（４）はその逆ですよね。これをやったけれど、あまり変化がないとか、コロナ対策は前からやっているので特に変わらないという意味なのか。この読み方がよく分からなかったので、教えていただきたいです。\n２番の心のケア、各学校の取組例というのは、基本、どこの学校もこの程度のことはやっているという読み方でいいのか、幾つかの学校で、うちはこういうのをやっていますというようなご報告の中から、報告されているのか、伺いたいと思います。\nその中の中黒の１つ目、いじめ・差別防止、相談体制や窓口の紹介というのは、どういう窓口を紹介されているのか教えていただきたいです。\nそれと、中黒の７つ目、市民科「ストレス悩みの解消方法」他の学習というのは、もともと市民科の授業のカリキュラムの中にそれがあるのか、このたびの事態に改めてこういうものをやったのか。\nそれからその次、ＨＥＡＴＲＴＳ、子ども家庭支援センターなどの専門的支援という、専門的というのをもう少し教えていただきたいと思います。\nそれから３番の最後の中黒です。保健室や別室での指導については、今、少しありましたけれども、そもそも保健室の先生というのは、学校の中でも子どもたちが心許せる、ほかの教科を教える先生とは違う視点をお持ちで、ここで救われている子どもたちも結構いるかなと思うのですけれど、そういう方たちによる指導というのも、ここに含まれているのか。それについて教えてください。"},{"i":127,"speaker":"矢部教育総合支援センター長","text":"７点、いただいたかと思います。１点目のグラフ等の読み方は、委員がおっしゃるとおりでございます。紙面の都合上、非常に簡潔に書きましたので、そのように読み取っていただければと思います。\n２点目の心のケアは、全ての学校から寄せて調査を集約したものなのですけれど、大体ほとんどの学校はこれをしているという認識で、捉えていただいて結構でございます。\nまた、窓口紹介につきましては、東京都や国が行っています窓口が１０以上あります、その一覧を、年２回から３回お配りしているところでございます。\n４点目の市民科につきましては、そもそもこの「ストレス悩みの解消方法」は最初からありますので、指導をこれまでも続けてございました。\n専門的支援につきましては、ＨＥＡＴＲＴＳについてはご存じの方が多いと思いますが、心理士もおりますし、警察ＯＢもおりますし、ソーシャルワーカーもおりますので、そういった専門的な知見で学校への助言をしたり、直接、お子さんを訪問して相談に乗ったりもしてございます。主に虐待につきましては、子ども家庭支援センターの係の方にご指導いただいたり、家庭に対応していただいているということでございます。\n最後の保健室につきましては、保健室での指導も実はありますけれども、委員おっしゃったように本当に心のよりどころとして、養護教諭は近い存在でございますので、ちょっとした相談から、保健室だったらできるかなということで、漢字をやったり自習したりということはございますので、指導という意味ではその程度のことと考えていただいて結構でございます。"},{"i":128,"speaker":"吉田委員","text":"それぞれありがとうございました。２番の心のケア、コロナ禍における子どもたちの心のケアについてということですが、基本的にはいつもやっていることを、この事態に当たって少し強化したというようなことかなと思います。やはりコロナ禍という事態については、ふだんの心のケアよりも一段と強化すべきところがあるかと思います。\nこの間、保健予防のことから、品川区の講演会に参加したのですけれども、その中では保健センターを含めていろいろ、特にそういう専門的な知見から心のケアが必要ということで、区内でもそういう講演会など行われていますし、そこに専門家もいらっしゃるし、これは教育委員会の問題ではありますけれど、コロナ禍におけるということで言えば、ぜひ所管、区長部局、教育委員会を超えて、そういう連携を図っていただけたらと思います。\nあと、保健室での養護教諭の役割というのは、私たちはとても重視していて。でも、その先生は１人しかいらっしゃらないので、なかなか発信は難しいのですというのが、正直なお声として養護教諭の方から伺っています。ぜひ、コロナ禍におけるということであれば、そういう方たちについての支援というのか、そういうこともぜひ検討していただきたいと思います。\nもしそれらについて何かご見解があれば、伺いたいと思います。"},{"i":129,"speaker":"矢部教育総合支援センター長","text":"最後の保健室についてでございますが、私も学校にいたときは、養護教諭とよくお話をしていました。やはり養護教諭の苦労もとても分かりますので、そこを認識しながら、ほかの教員やあいている教員などにも手伝ってもらって、みんなで子どもたちを守っていく、そういうスタンスから、少し心の負担を軽減させてきたという経緯がございます。"},{"i":130,"speaker":"松澤委員","text":"２点ほどお聞きしたいのは、スクールカウンセラーの全員面談、大変だと思いますけれども。今、ＩＣＴで１人１台タブレットが配られていますよね。心のケアというのは、声を上げられる機会というのがとても大事だと思いますので、ネットからの発信といいますか、ｉＰａｄにはチャイルドラインのＱＲコードもありますけれども、そういったものをしっかり活用して、子どもたちの声を聞くというのは、とてもいい取組だと思いますので、そういうものもこの取組の中に入ればいいと思うのが１点。\nあと、ＰＴＡと連携した各種講演会というのがありますけれど、これはＰＴＡの家庭教育学級だと思うのですけれども、そうですよね、私、一貫して言っているのは、子育ては親育てで、子どもの講座と親の講座がどうしても分かれてしまう。これは一緒にやるべきだと常にずっと思っていますので、やっていただいているのは私も知っています、でも、平日の午後とか、なかなか親が集まれない時間とか、各学校の都合だからそれは仕方ないと思うのですけれども、やはり学校公開でやるなど、ある程度の工夫があっていいのかなというのは、正直ずっと思っています。その辺について、２点お願いします。"},{"i":131,"speaker":"矢部教育総合支援センター長","text":"２点いただきました。タブレットのほうはチャイルドラインと、中学生のほうはアイシグナル、そして東京都のほうの相談窓口も今回入れさせていただきましたので、それぞれ子どもたちが活用できるようなってございます。また、アイシグナルについては直接我々に来るものでございますので、大事に対応してまいりたいと考えております。\n２点目、保護者への周知というか、一緒に勉強という内容だと思いますが、委員ご指摘のように、家庭教育学級では「怒らない子育て」という講演会、また、「新型コロナとその他のリスク」ということで、東京慈恵会医科大学の先生をお呼びしての講演、また、保護者向けのゲートキーパー研修は、今回保健予防課からもご案内がありまして、かなりの人数だったと聞いております。土曜日にやっているということも今回情報の中にありましたので、できる限り保護者と一緒に、守っていきたいと考えております。"},{"i":132,"speaker":"有馬庶務課長","text":"ＰＴＡの関係で、去年は、秋の親と子の芸術鑑賞会とか、音楽発表会が中止になりましたけれども、今年は、この２つを合わせた「しながわドリームフェスティバル」を開催できたりしておりますので、積極的にそういう面も支援していきたいと考えております。"},{"i":133,"speaker":"つる委員","text":"１番の（３）、改善したと答えた理由のその他で、実験や実習の機会が増えたということで、これは非常にいいことだと思うのです。やはり運動の機会とか、外で学習するとか、そういう機会がなかなかとれなかった中で、それができるようになってきたということで、それだけでも子どもにとってのストレスの違いというか、学習で獲得する濃度も全然違うと思うのです。当然、コロナという状況の中ですけれど、今までできなかった分を取り返すような形で、ぜひ現場の指導ではお願いしたいと思います。\nその上で、目の前の現実というのがいろいろあって、１年、２年たって、２０２０年の１年間と２０２１年の１年間では、また子どもたち自身も、当然、コロナが不安で登校できない児童・生徒がまだいらっしゃるわけですけれども、その捉え方というのは変わってきたのかなというふうに思うのです。悲惨な現実というのはもう世界中共通であって、その事実をどう捉えていくかというところを教育につなげるという観点を、かつてもいろいろ質疑させていただいたことがあったと思うのです。目の前の川の水を、甘く感じるのか、苦く感じるのか、辛く感じるのかというのは、主体である一人一人の立ち位置というか、そういった部分にもとても影響してくるのかなというところでは、それを指導、一緒になって学んでいくのが、教員の役割なのだろうと思う中では、コロナという脅威について、まさに今までの約２年間、それを生かしていただいた部分といいますか、どうしても怖い、だから対策しなきゃ、あれしちゃいけない、これしちゃいけないということではなく、それを生かした部分というところで、まさに心のケアというか。ストレスがなければ人は成長できないと思うのです。なので、そういう部分で生かした点というのは、何かあるのでしょうか。教えてください。"},{"i":134,"speaker":"矢部教育総合支援センター長","text":"コロナ禍のこの現状を、どうやって教育活動に生かしたかという例かと存じます。幾つかありますけれども、コロナを直接、世界の状況ということで社会科などで取り上げていることは、もちろんあると思います。また、政治の働きについては６年生で行いますけれど、社会科の中で、コロナ禍でどういうふうに政治が動くかというようなところも、取り上げられた事例がございます。また保健につきましては、当然ですけれども病気の予防ということで取り上げております。\nまた、委員もおっしゃっていましたけれど、いじめとか偏見、今回いじめが減っているというのは示したとおりでございますが、それは国のほうからも、今回のコロナ禍において、より人への思いやりを持つという指導が徹底されたのではないかという説明もございましたので、それも関係していると思います。\nあと、セルフケアです。先ほどご指摘がありましたとおり、市民科のほうでも自分でストレスをどういうふうに解消したらいいか、人にどうやって話したらいいかという学びもございますので、様々な場所で、機会で、学習していると捉えています。"},{"i":135,"speaker":"つる委員","text":"ありがとうございます。ぜひ眼前の危機を、危機だけにするのではなくて、それをどう捉えて、どう生かし、乗り越えていけるかという、まさに生き抜く力というのでしょうか。それをしっかりとつけていく、まさにチャンスとして捉えていかなければいけないのかなと。まさに心のケアにも通じる部分かなと思います。\nそれと、先ほど松澤委員からも質疑がありまして、親御さんへのケアといいましょうか。１番の（４）、２つ目のポツに不登校が増加と、これはいろいろ数字上では、東京都と比較して低いとかあるわけですが、１人でもいれば、その子に対してオール・フォー・ワンではないですが、しっかりと対応していかなければいけないということだと思うのですけれども。ただ、増加するもともとの要因というのでしょうか、もともと家庭環境とか、置かれている状況が、様々な、複雑な中で、ちょっとしたきっかけで不登校になってしまう。それがまさに先ほどの、コロナという危機に対してどう対応できるかという部分になってくると思うのですけれども。\nそこの意味において、やはり親に対するいろいろな講習や研修といった機会、先ほど松澤委員へのご答弁であったわけですけれども、そこのところをどういうふうに捉えて、今後、小学校ないし義務教育学校の前期課程が特にだと思うのですけれども、特に低学年の親御さんへのケアが必要なのかなと思うのです。\n例えば幼稚園や保育園というのは、親がいろいろな意味で直接園に接するのです。毎日、朝、帰り、子どもが園の保育士や幼稚園教諭に接するだけでなく、親もダイレクトに、子どもがお世話になっている保育士や幼稚園教諭に接するのです。そうすると、そこで親もいろいろな話を１分、３０秒の世界かもしれない、本当に僅かな時間だけれど、ちょっと言葉を交わすだけで、子どものことも含めて自分も聞いてもらった、受けとめてもらえたという部分があるのだと思うのです。実際、私も実感としてあるのです。保育士に会うことでいろいろ聞いてもらえて、自分の頑張ってきたことが間違ってないのだとか、安心できるのです。けれど、学校は、自分で行って自分で帰ってくるのですよね。子どもから、どうだったか聞く、それはそれで一方でいいのだけれども、ただ、親は何もそういう機会、きっかけ、チャンスがない。それが連絡帳だったり、直接副校長に連絡してくださいとか、担任に連絡しなさいと。大体午後３時半ぐらいになってくると、何かあれば電話がかかってくるとか。そういうのはあるのですけれども。\nそういう部分で、先ほど松澤委員がおっしゃった、そういう機会というのはぜひ増やしていただきたいと思うのです。教員の負担がいろいろ増えてしまうとか、そういうのはナンセンスなのですが、ただ、保護者の方、ＰＴＡというのは小学校では強いわけですけれども、教員の方の保護者とのコミュニケーションというのでしょうか、もう少し何かしらの形で、いい意味で何かできる仕組みがあればいいのかなと思うのです。だから、これは別に答弁は要りません、要望で、そういう機会を今後、先ほど松澤委員との質疑でもあったので、ぜひ何か考えていただければと思います。"},{"i":136,"speaker":"湯澤副委員長","text":"それぞれありがとうございます。私からも何点か質問させていただきたいと思います。今、つる委員がおっしゃったように、区立学校といいましても１年生から９年生までということで、年齢としても６歳から１５歳と、特に小学校だと６歳からですので、例えば自分の体に異変が起きた、そういったことにすら気づかなかったり、保育園、幼稚園のときにはいろいろなことを帰りがけに、親も聞くことができる、そういうことがあったのが、小学校になるともう、そういったこともない。そういったところで自分の異変に気づかなかったり、といった子たちもいるのではないかと思います。また学年が上がってくると、今度は人と違うという、変化に対して恥じらいを持ってくる。そういったところで人に相談するのがなかなか難しくなってきたり、ということがあるかと思うのですけれども。\nそういった中で、例えば年齢によって、特に小学生はそうだと思うのですけれど、小学生ということでなく、年齢や性格といったところで、何か心のケアに対して配慮している部分、そういったところのお考えがあるのか。また、教育委員会として具体的にどういった取組をしているのかというのもそうですし、教員たちがそういったところに気づいてあげられるとか、研修等の取組などもあれば、教えていただきたいと思います。"},{"i":137,"speaker":"矢部教育総合支援センター長","text":"主に小学生へのアプローチでお答えしたいと考えます。先ほどのお話にもありましたとおり、保護者への機会については昨年度は特に、保護者会もオンラインになってしまったり、直接お話しすることができなかったというところもあります。今年度、直接お話しすることはぐっと増えたと聞いておりますので、一つは保護者会。それと、今は端末を使ってロイロノートでつながっているという事例も聞いてございます。また、これまでどおり連絡帳で、本当に毎日のように保護者が担任に相談、また今日の報告をされる方もいらっしゃいます。そうやって個々に合わせていくことが大切かと思います。\n総じて、コロナ禍でございますので、これまでどおりの対応だけではなく、さらにお子さんに関わっていくことが、特に担任には必要なことだろうと感じています。区教委としましてはこれまでどおり、生活アンケートですとか、校長会で必要な連絡をするとかいうことで、あとは個別、具体的な取組について好事例を紹介しながら、応援していきたいと考えております。\n教員の研修につきましては、様々な研修があるのですけれども、今回は小学生から離れてしまうかもしれません、大きな学年の心のケアとしまして、自殺予防の取組については随分ありまして、注意喚起の通知はもちろんですが、生活指導主任会での情報共有、また、１人１台のタブレットにＳＯＳのフォルダ作りもしました。前回は９月８日、品川教育の日に、いじめ自殺防止の講演会を、講師を呼んでお話しいただいたところです。また、１１月１５日の学校長会では教育長からも、お子さんの命についてのお話があったところでございます。\n学年差はありますけれど、とにかく小さな子ども、大きなお子さんもよく見て、観察して、学校体制として早急に対応するというような内容は、これまでも伝えてきたところでございますので、これからも進めてまいりたいと思っています。"},{"i":138,"speaker":"湯澤副委員長","text":"ありがとうございます。それと、児童・生徒のコロナ不安を理由として登校できなかった、そういったところで、９月から１１月においてかなり激減しているというのは分かるのですけれども、中学生に関しては、９月の時点でもそこまで減っていないかなというのは、何か理由が分かっていれば教えていただきたいと思います。\nあと、登校できなかった理由というところで、（３）を見て分かるところもあるのですけれども、例えば不登校の方の中には、親御さんから登校しないようにと言われたケースなどもあったのか、教えていただきたいと思います。"},{"i":139,"speaker":"矢部教育総合支援センター長","text":"２点とも同じような回答になるかと思います。実際、これを調べただけで終わらず、我々も少し学校のほうに聞き取りをしたところ、お休みの理由は様々でございますが、中学生で多かったのは、もともと登校渋りの傾向があったお子さんです。そのほか、人数が少ないので具体的に申し上げませんけれども、受験に関わることや、保護者のワクチンに対する考え方、これが合わなくて登校させていないという事例がございました。"},{"i":140,"speaker":"湯澤副委員長","text":"ありがとうございます。そういった理由があるということが分かりました。これまで委員の皆さんの中で、子どもだけでなく保護者に関しても、心のケアといったものが必要なのではないかというところは、私自身も感じています。やはり虐待が増えてしまうといったところに関しても、普通なら、かわいい我が子に手を上げるということはなかなか、虐待してしまうということはないと思うのですけれども、やはり環境の変化とか、コロナによる不安、そういったところで保護者のほうにも、そういった心のケアが実は必要だというところがあるのではないかと思っております。日本小児保健協会でも、保護者がコロナへの正しい知識を持つことが、自身のストレスを減らし、そして子どもへの虐待も減らすことにつながるというようなことを言っております。\nそういった中で、心のケアとして、ＰＴＡと連携した各種講演会の実施というのが、保護者に向けてのそういったメッセージなのかなと思うのですけれども、ほかに区が保護者に対して何か発信しているようなことがあれば、それも教えていただきたいと思います。"},{"i":141,"speaker":"矢部教育総合支援センター長","text":"重複するところがあるかもしれませんが、先ほどの保健予防課のゲートキーパー研修は、保護者が対象で募集がございまして、そちらのご案内をしています。また、学校ではこれまでも、お子さんも含めて保護者にも、これだけ学校は感染対策をしていますという情報が伝わるように、学校だより等を発信して、少しでも安心感を与えるような取組をしております。\nまた、具体になりますけれども、保健センターとつながって、保護者がご相談に行ったり、お子さんを見ていただいたりということも、事例としてはございます。"},{"i":142,"speaker":"有馬庶務課長","text":"もう１点ですけれども、我々が今年の夏にＰＴＡの行事でやったものについても、「コロナ禍でも快適に過ごすヒント」という形で、ＰＴＡ向けに講演するものですし、先ほどご紹介した立正大学の「コロナ禍のメンタルヘルスを考える」というのは、品川区と共催ということでの事業ですので、そのような取組もやっていると認識しております。"},{"i":143,"speaker":"湯澤副委員長","text":"本当に子どもたちの心のケアというのは、学校が対処するだけでなく、やはり親子、そして家族で支え合いながら行うべきだと考えております。ぜひ、他の自治体でもよい取組などがありましたら、随時取り入れていただきまして、子どもたちの心のケアに、より一層努めていただきたいと思います。"},{"i":144,"speaker":"あくつ委員長","text":"ほかはよろしいですか。では、私から最後に１点だけ、出なかったところで伺います。\n１番の児童・生徒の実態の（６）、虐待相談件数（センター対応分）が、明らかに増えている、２倍になっているというところで、一般的に考えれば、家にいる時間が増えたからなのかなと。この相談をしたというのは、親御さんなのか、本人なのか。そもそもこれは恐らく氷山の一角であって、よほどでないと、こういうことはなかなか本人は声を上げられない。もしくは両親の片方が相談をするとか、近所が、ということもあると思うのですけれども。\n次の文教委員会では、子ども未来部の中で、子どもたち・子育て家庭の支援というものを所管事務調査にしているのですが、ここについて、主に児童相談所の部分というのはあるかと思うのですけれども、品川区教育委員会として、コロナによる非常事態なのかもしれませんが、氷山の一角とも思われるこういう急増していることについて、教員の皆さんがご存じなのかどうか、というところが一つ。それと、こういったことは一つ一つ対応されていると思うのですけれども、事例があれば若干ご紹介いただいて、どういうことが増えているのかということ、これを、これからどのように改善していくために取り組まれているのかということを、最後にお伺いしたいと思います。"},{"i":145,"speaker":"矢部教育総合支援センター長","text":"教員への周知でございますが、毎年生活指導主任会で、子ども家庭支援センターの職員を招聘して、虐待についての理解と通告義務のこと、また、これからの流れの説明をしているところでございます。校長会につきましては、私もかなりの頻度で虐待が増えていることは伝えておりますので、学校を回った印象としても、虐待についてはかなり意識の高い反応が返ってまいります。\n２点目、どのような事例という中で、親からが多いのか、本人からか、様々でございます。きっかけについては、担任が傷、あざを発見する場合もございますし、スクールカウンセラーの相談の中で、こんなことされたということが子どもから分かることもございます。また、生活アンケートですとか、体罰防止のアンケートもございます、その中で暴力を見たとか聞いた、自分がやられたということで、記述してくる場合もありますので、それを受け取って、管理職が中心に聞き取りをする。そういう流れが多いです。\nコロナ禍ということでありますと、やはりお話がありましたように、ずっと家に保護者がいらっしゃるということ、経済的に必ずしもうまく回ってないおうちもありますので、イライラがつのる場合もあります。また、お子さん自身が少し特性を持っていて、じっとしていられないお子さんが言うことを聞かないことで手を上げてしまう、ということもございます。本人もありますし、保護者からの訴えもございます。\n学校としましてこれからというのは、我々としましては、とにかく早期発見して、すぐつなぐという、学校としてはそこが一番大事かと思います。あとは専門の子ども家庭支援センターや児童相談所というところにつないでいきたいと思っております。"},{"i":146,"speaker":"あくつ委員長","text":"ありがとうございました。\nよろしいでしょうか。\nご発言がないようですので、以上で、本日の所管事務調査を終了いたします。\n────────────────────────────────────────────\n３ その他\n(1) 議会閉会中継続審査調査事項について"},{"i":147,"speaker":"あくつ委員長","text":"次に、予定表３のその他を議題に供します。\nまず、(1)議会閉会中継続審査調査事項についてでございますが、お手元の申出書案のとおりでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":148,"speaker":"あくつ委員長","text":"それでは、この案のとおり申し出ます。\n────────────────────────────────────────────\n(2) 委員長報告について"},{"i":149,"speaker":"あくつ委員長","text":"次に、(2)委員長報告についてでございます。\n昨日の議案審査の委員長報告については、正副委員長にご一任いただきたいと思いますが、よろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":150,"speaker":"あくつ委員長","text":"ありがとうございます。\nそれでは、正副でまとめさせていただきます。\n────────────────────────────────────────────\n(3) その他"},{"i":151,"speaker":"あくつ委員長","text":"次に、(3)その他を議題に供します。\nその他で何かございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":152,"speaker":"あくつ委員長","text":"ないようですので、以上でその他を終了いたします。\n以上で本日の予定は全て終了いたしました。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ０時２３分閉会"}]});
